#!/usr/bin/env python3
"""从本地模板、WebP和已核验WOFF重建独立样稿；不联网、不修改原件。"""
from pathlib import Path
from fontTools.ttLib import TTFont
import base64,hashlib,json,re,shutil,subprocess
root=Path(__file__).resolve().parents[4];assets=root/'素材/NED/网页展示_V01';dest=root/'UI设计/NED网页展示/V01';dest.mkdir(parents=True,exist_ok=True)
s=Path(__file__).with_name('页面模板.html').read_text()
english={
'skip':'Skip to content','work':'Work','about':'About','contact':'Contact','heroDesc':'Helping people feel the atmosphere<br>and understand the product.','heroKind':'NED · E-commerce visuals · Self-initiated concept','seeDesign':'Explore the work','scopeShort':'Product images / Listing / A+ / Brand story / Banners','introTitle':'One lamp.<br>Four communication tasks.','introBody':'An e-commerce visual exploration for the NED Eric lamp, connecting product recognition, clear controls and the atmosphere of everyday life. Warm neutrals and natural materials hold the work together, while each part answers a different question.','scopeFact':'A portfolio simulation in an Amazon US context. Not a brand commission; not launched or advertised.','project':'Project','projectValue':'AI-assisted e-commerce visual concept','focus':'Focus','focusValue':'Content, design decisions and multi-device adaptation','deliverables':'Deliverables','deliverableValue':'Product images, Listing, Premium A+, brand story and banners','myRole':'My contribution','myRoleBody':'Project goals and visual direction, reference and version selection, review feedback and decisions on revisions.','aiRole':'AI collaboration','aiRoleBody':'Research, image generation and compositing, English copy, SVG layout and exports in collaboration with Codex and AI tools.','decisionTitle':'A shared visual language.<br>Different everyday moments.','decisionLead':'The product anchors the composition. Settings and content carry the story, giving each image a distinct job within a coherent whole.','sceneCaption':'Existing dining scene at dusk · light and materials distinguish the setting','productFocus':'Keep the product clear.','productFocusBody':'The shade, sand-colored finish and top knob are recognition points. The setting supports the product; the explanation supports understanding.','d1':'Recognize the product','d1Body':'A clear overall view and a sense of proportion establish the first impression without letting the setting overwhelm the lamp.','d2':'Understand the controls','d2Body':'Separate pressing from turning so the image and words answer a specific question about use.','d3':'Imagine everyday use','d3Body':'Daylight, night and dusk give the settings different roles while retaining a shared warm-neutral base.','outcomeTitle':'Each image answers<br>a buying question.','outcomeLead':'From what it is to how it works. The original product-image designs remain intact below; web text explains their purpose.','productArt':'Product and setting','productArtBody':'Show the whole product, then its place at home. Scale and setting work together to establish the impression.','controlArt':'Make the action specific','controlArtBody':'Pressing and turning sit side by side. Actions, images and words correspond, reducing the need to search between them.','browseEight':'Browse all 8 product images','specNote':'Specifications shown in the artwork are source claims, not measurements. These are concept deliverables, not live listing screenshots.','archiveTitle':'The complete work continues.','archiveNote':'This first study tests the web opening, narrative and product-image presentation. Full originals for the other three areas remain available; their web layout will follow review feedback.','aplusSummary':'10 desktop modules, 11 mobile image/text states · View full original','storyTitle':'Brand story','storySummary':'Complete desktop card group and four mobile story states · View full original','bannerSummary':'Three themes, six adaptations · View full original','reflectionTitle':'Let the work show<br>the decisions.','reflectionBody':'The exploration leaves a traceable record of images, versions and revisions. Product edges, setting differences and mobile state coverage suggest a useful next step: check key samples before extending the full set.','reflectionLimit':'There are no sales or conversion results. The work describes a design process and collaboration decisions.','backWork':'Back to work','homeTitle':'Stay curious.<br>Design with care.','homeIntro':'I’m Migo, exploring AIGC and commercial visual design through self-initiated projects, content organization and design decisions.','viewWork':'View the work','workSummary':'Helping people feel the atmosphere and understand the product.','workCategory':'E-commerce visuals · AI collaboration · Self-initiated concept','viewCase':'Explore the NED case','aboutTitle':'Build judgment<br>through real projects.','aboutBody':'I focus on content and expression in commercial visual design, exploring AI collaboration through self-initiated projects. References, version decisions and review feedback make the process understandable.','aboutIP':'Migo is the designer and brand owner. Beedog is the brand character; its visual identity is still in development and is reserved for later integration.','contactTitle':'Roles and design collaborations','contactBody':'Contact details will be added after confirmation.','contactPending':'Contact details pending','footerText':'Personal portfolio · NED web visual study · Chinese and English drafts pending review','backHome':'Back to home','close':'Close','previous':'Previous','next':'Next','openOriginal':'Open full-size image'}
translations={}
for tag,key,value in re.findall(r'<([a-z0-9]+)[^>]*data-copy="([^"]+)"[^>]*>(.*?)</\1>',s,re.S):
 assert key in english,key
 translations[key]={'zh':value,'en':english[key]}
assert set(translations)==set(english),(set(english)-set(translations))
# 使用本批已核验的WOFF字形子集，不依赖全量源字体或再次改写派生文件。
for key,name in [('LATIN','界面西文.woff'),('CJK','界面中文.woff')]:
 s=s.replace('__FONT_'+key+'__','data:font/woff;base64,'+base64.b64encode((assets/name).read_bytes()).decode())
text=s+json.dumps(translations,ensure_ascii=False)+'主图产品场景旋钮操作光色调节夜间无线续航尺寸材质户外使用多场景使用'
cjk=TTFont(assets/'界面中文.woff');cmap=cjk.getBestCmap();missing=sorted({ch for ch in text if '\u4e00'<=ch<='\u9fff' and ord(ch) not in cmap});cjk.close()
assert not missing,'新增文字需要重新生成中文字体子集：'+''.join(missing)
record=json.loads((assets/'交付清单.json').read_text())
def image(name):return 'data:image/webp;base64,'+base64.b64encode((assets/name).read_bytes()).decode()
for token,name in [('HERO','封面_原场景裁切.webp'),('TWILIGHT','策略_餐桌暮色.webp'),('CUTOUT','策略_产品透明抠图.webp'),('GOODS1','01_产品展示_V02.webp'),('GOODS2','02_旋钮操作_V02.webp')]:s=s.replace('__IMAGE_'+token+'__',image(name))
labels=[('主图 V01','Main image V01'),('产品场景 V02','Product setting V02'),('旋钮操作 V02','Knob controls V02'),('光色调节 V01','Color temperature V01'),('夜间无线续航 V02','Night and runtime V02'),('尺寸材质 V02','Size and material V02'),('户外使用 V02','Outdoor use V02'),('多场景使用 V02','Multiple settings V02')]
goods=sorted(p for p in assets.glob('*.webp') if p.name[0].isdigit());assert len(goods)==8
thumbs=[];art=[]
for i,(p,(zh,en)) in enumerate(zip(goods,labels)):
 thumbs.append(f'<button type="button" data-open="{i}" aria-label="放大：{zh}"><img data-thumb="{i}" src="{image(p.name)}" alt="{zh}" width="1254" height="1254" loading="lazy"></button>')
 art.append({'index':i,'name':p.name,'zh':zh,'en':en})
s=s.replace('__THUMBNAILS__',''.join(thumbs));s=s.replace('const artwork=__ARTWORK_DATA__;','const artwork='+json.dumps(art,ensure_ascii=False)+'.map(item=>({...item,src:document.querySelector(\'[data-thumb="\'+item.index+\'"]\').src}));')
s=s.replace('__TRANSLATIONS__',json.dumps(translations,ensure_ascii=False))
for suffix,path in [('APLUS','02_高级A+'),('STORY','03_品牌故事'),('BANNERS','04_Banner系统')]:
 from urllib.parse import quote
 full='作品项目/NED_Eric_Lamp_氛围灯/制作交付/作品集展示/成果展示/V04/'+path+'/README.md'

 s=s.replace('__LINK_'+suffix+'__','https://github.com/Migo1203/AIGC/blob/'+record['来源AIGC提交']+'/'+quote(full))
for key,d in [('DOWN','M5 5l14 14M5 19h14V5'),('RIGHT','M4 12h16m-6-6 6 6-6 6'),('UP','M5 19 19 5M5 5h14v14')]:s=s.replace('__ARROW_'+key+'__','<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="'+d+'"/></svg>')
assert not re.search(r'__[A-Z_0-9]+__',s)
(dest/'展示样稿.html').write_text(s)
print('已构建单文件样稿：',len(s.encode()),'字节；',len(translations),'个中英文文字键，11张真实图像，2份本地字体子集。')
